mapper.select:
SELECT * FROM ui_elements

ORDER BY sort_order ASC, page_id ASC, module_tag ASC, name_zh ASC, source ASC

    LIMIT #{limit}
    OFFSET #{offset}

SELECT * FROM ui_elements
WHERE app_id = #{appId} AND platform = #{platform} AND name_en = #{nameEn}
AND source = #{source}
ORDER BY CASE source WHEN 'HUMAN_AI' THEN 0 WHEN 'SOURCE_CODE' THEN 1 ELSE 2 END
LIMIT 1

SELECT * FROM ui_elements
WHERE app_id = #{appId}
  AND platform = #{platform}
  AND locator_type = #{locatorType}
  AND locator_value = #{locatorValue}
ORDER BY
    CASE status WHEN 'ACTIVE' THEN 0 WHEN 'CANDIDATE' THEN 1 ELSE 2 END,
    updated_at DESC
LIMIT 1

SELECT * FROM ui_elements
WHERE enabled = 1
AND app_id = #{appId}
AND platform = #{platform}
AND (
    locator_value = #{locatorValue}
    OR locator_value LIKE CONCAT('%', #{locatorValue}, '%')

        OR locator_value LIKE CONCAT('%', #{shortId})
        OR locator_value LIKE CONCAT('%/', #{shortId})

)
ORDER BY
    CASE WHEN locator_value = #{locatorValue} THEN 0 ELSE 1 END,
    CASE status WHEN 'ACTIVE' THEN 0 WHEN 'CANDIDATE' THEN 1 ELSE 2 END,
    updated_at DESC
LIMIT #{limit}
